def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    from collections import Counter,defaultdict
    tiles={}; counts=Counter()
    # Frame/tile lattice has 5x5 motifs, stride 7, origin (1,1), with 3x3 interior.
    for r0 in range(1,h,7):
        for c0 in range(1,w,7):
            if r0+2<h and c0+2<w:
                v=grid[r0+1][c0+1]
                if v: tiles[(r0,c0)]=v; counts[v]+=1
    base=counts.most_common(1)[0][0] if counts else None
    rows=defaultdict(list); cols=defaultdict(list)
    for (r0,c0),v in tiles.items():
        if v!=base:
            rows[(r0,v)].append(c0)
            cols[(c0,v)].append(r0)
    for (r0,v),starts in rows.items():
        starts.sort()
        for a,b in zip(starts,starts[1:]):
            for r in range(r0+1,r0+4):
                for c in range(a+5,b):
                    if grid[r][c]==0: out[r][c]=v
    for (c0,v),starts in cols.items():
        starts.sort()
        for a,b in zip(starts,starts[1:]):
            for r in range(a+5,b):
                for c in range(c0+1,c0+4):
                    if grid[r][c]==0: out[r][c]=v
    return out
